const getMmdDeepDive = (remedyName: string, aiData: any) => {
  if (!remedyName) return null;
  const aiDeepDive = aiData?.materia_medica_analysis?.remedy_deep_dive;
  if (aiDeepDive && (aiDeepDive.remedy?.toLowerCase().includes(remedyName.toLowerCase()) || remedyName.toLowerCase().includes(aiDeepDive.remedy?.toLowerCase()))) {
    return aiDeepDive;
  }
  const keys = Object.keys(REMEDIES_DEEP_DIVE_TEMPLATES);
  const foundKey = keys.find(k => k.toLowerCase().includes(remedyName.toLowerCase()) || remedyName.toLowerCase().includes(k.toLowerCase()));
  if (foundKey) {
    return REMEDIES_DEEP_DIVE_TEMPLATES[foundKey];
  }
  return aiDeepDive || REMEDIES_DEEP_DIVE_TEMPLATES["Sulphur"];
};

