const getDurationMonths = (duration: string) => {
  if (duration.includes("3-Month")) return 3;
  if (duration.includes("6-Month")) return 6;
  if (duration.includes("12-Month")) return 12;
  return 1;
};

const getDurationValue = (duration: string) => {
  if (duration.includes("3-Month")) return 3;
  if (duration.includes("6-Month")) return 6;
  if (duration.includes("12-Month")) return 12;
  if (duration.includes("2-Week")) return 2;
  if (duration.includes("4-Week")) return 4;
  if (duration.includes("8-Week")) return 8;
  if (duration.includes("12-Week")) return 12;
  return 1;
};
// careLevelsDetails and surchargesLookup are imported from centralized pricingConfig

const getCareLevelKey = (level: string) => {
  return normalizeCareLevelName(level);
};

const getCareLevelRate = (level: string, cycle: string, conditions: number = 1) => {
  const key = getCareLevelKey(level);
  const isWeekly = cycle === "Weekly";
  const basePrice = isWeekly ? CARE_LEVELS_DETAILS[key].weeklyPrice : CARE_LEVELS_DETAILS[key].monthlyPrice;
  void conditions;
  return basePrice;
};

const calculatePlannerPricing = (
  level: string,
  cycle: "monthly" | "weekly",
  duration: number,
  conditions: number
) => {
  const details = CARE_LEVELS_DETAILS[level as keyof typeof CARE_LEVELS_DETAILS] || CARE_LEVELS_DETAILS.focused;
  const basePrice = cycle === "weekly" ? details.weeklyPrice : details.monthlyPrice;
  const surcharge = 0;
  const adjustedBasePrice = basePrice;
  const rawTotal = adjustedBasePrice * duration;
  const discountPercent = 0;
  const discountAmount = 0;
  const finalPriceBeforeConcession = rawTotal;
  
  return {
    basePrice,
    surcharge,
    adjustedBasePrice,
    rawTotal,
    discountPercent,
    discountAmount,
    finalPriceBeforeConcession
  };
};

