  const handleLaptopFileImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsImportingLocalFile(true);
    setAnalyzerFiles((prev) => [...prev, { name: file.name, size: `${(file.size / (1024 * 1024)).toFixed(2)} MB`, type: "pdf", source: "local" }]);

    try {
      const reader = new FileReader();
      reader.onload = async (event) => {
        try {
          const resultStr = event.target?.result as string;
          const base64Data = resultStr.split(",")[1];

          const res = await fetch("/api/import-lab", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              fileData: base64Data,
              mimeType: file.type || "application/octet-stream",
              fileName: file.name
            })
          });

          const data = await res.json();
          if (data.success && data.text) {
            setAnalyzerRawText(data.text);
            setIsAnalyzerLoading(true);
            const analyzeRes = await fetchAIDiagnostics("analyzer", {
              rawText: data.text
            });
            if (analyzeRes.success) {
              setAnalyzerResult(JSON.parse(analyzeRes.analysis));
            }
            setIsAnalyzerLoading(false);
          } else {
            console.warn("AI extraction returned no text. Using fallback template based on filename.");
            const lowerName = file.name.toLowerCase();
            if (lowerName.includes("cbc") || lowerName.includes("blood")) {
              triggerSample("CBC");
            } else if (lowerName.includes("thyroid") || lowerName.includes("tsh")) {
              triggerSample("Thyroid");
            } else if (lowerName.includes("diabetes") || lowerName.includes("hba1c") || lowerName.includes("glucose")) {
              triggerSample("Diabetes");
            } else if (lowerName.includes("liver") || lowerName.includes("lft")) {
              triggerSample("LFT");
            } else if (lowerName.includes("kidney") || lowerName.includes("kft") || lowerName.includes("creatinine")) {
              triggerSample("KFT");
            } else {
              triggerSample("Thyroid");
            }
          }
        } catch (err) {
          console.error("Error analyzing uploaded local file:", err);
          // Fallback on error
          triggerSample("CBC");
        } finally {
          setIsImportingLocalFile(false);
        }
      };
      reader.readAsDataURL(file);
    } catch (err) {
      console.error("Failed to read file reader data:", err);
      setIsImportingLocalFile(false);
    }
  };

