  const [saveStatus, setSaveStatus] = useState("");
  const [activeAiTab, setActiveAiTab] = useState<"synthesis" | "vectors" | "checklists" | "network" | "reasoning">("synthesis");
  const [confirmActiveRemedy, setConfirmActiveRemedy] = useState<string>("");
