  // 3. Clinical Decision Support States
  const [cdsThermalState, setCdsThermalState] = useState<"Hot" | "Chilly" | "Ambi">("Chilly");
  const [cdsFoodDesires, setCdsFoodDesires] = useState<string[]>([]);
  const [cdsWorseFrom, setCdsWorseFrom] = useState<string[]>([]);
  const [cdsPrimarySymptom, setCdsPrimarySymptom] = useState("");
