  // Load Patients from Firestore in real-time
  // MULTI-TENANT: Admins see all patients; doctors only see their own (server-side enforced)
  useEffect(() => {
    if (!session?.uid || !authReady) return;

    // Build the appropriate query based on role
    const patientsRef = collection(db, "patients");
    const isSuperAdmin = session.role === "admin" || (session.role && normalizeRole(session.role) === "super-admin");
    const q = isSuperAdmin
      ? query(patientsRef, orderBy("createdAt", "desc"))
      : query(patientsRef, where("assignedDoctor", "==", session.uid));

    const unsubscribe = onSnapshot(q, async (snapshot) => {
      if (snapshot.empty) {
        console.log("Firestore patients collection is empty for this scope.");
        setPatients([]);
      } else {
        const list: Patient[] = [];
        snapshot.forEach((doc) => {
          list.push(doc.data() as Patient);
        });
        if (!isSuperAdmin) {
          list.sort((a, b) => {
            const timeA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
            const timeB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
            return timeB - timeA;
          });
        }
        setPatients(list);
      }
    }, (error) => {
      console.error("Error listening to patients collection:", error);
    });

    return () => unsubscribe();
  }, [session, authReady]);


  // Filter patients based on search and roles
  const filteredPatients = patients.filter((p) => {
    // 1. Role-based visibility
    const isSuperAdmin = session ? (session.role === "admin" || (session.role && normalizeRole(session.role) === "super-admin")) : false;
    if (session && !isSuperAdmin) {
      // Junior doctor: Only see assigned patients
      if (p.assignedDoctor !== session.uid && !session.assignedPatients.includes(p.id)) {
        return false;
      }
    }
    // 2. Smart Fuzzy Search Match
    if (!searchTerm) return true;
    const term = searchTerm.toLowerCase();
    
    const matchesBasic = (
      p.name.toLowerCase().includes(term) ||
      p.id.toLowerCase().includes(term) ||
      p.complaint.toLowerCase().includes(term) ||
      p.location.toLowerCase().includes(term) ||
      (p.email && p.email.toLowerCase().includes(term)) ||
      (p.phone && p.phone.toLowerCase().includes(term)) ||
      (p.careLevel && p.careLevel.toLowerCase().includes(term))
    );

    let ageMatches = false;
    const ageNum = parseInt(p.age);
    if (!isNaN(ageNum)) {
      if (term === "child" && ageNum < 18) ageMatches = true;
      if ((term === "senior" || term === "elderly") && ageNum >= 60) ageMatches = true;
      if (term === "adult" && ageNum >= 18 && ageNum < 60) ageMatches = true;
      if (p.age === term) ageMatches = true;
    }

    return matchesBasic || ageMatches;
  });

  // Filter pending intakes for queue display
  const pendingIntakes = patients.filter((p) => p.status === "pending" || p.status === "pending_plan");

  // Filter patients due for checkups/follow-ups (no activity in 14 days or lastSeen > 30 days)
  const dueFollowUpPatients = useMemo(() => {
    return patients.filter((p) => {
      if (p.status === "pending" || p.status === "pending_plan") return false;
      const registeredDate = new Date(p.createdAt);
      const daysSinceRegistration = (Date.now() - registeredDate.getTime()) / (1000 * 60 * 60 * 24);
      
      if (p.lastSeen) {
        const lastSeenDate = new Date(p.lastSeen);
        const daysSinceLastSeen = (Date.now() - lastSeenDate.getTime()) / (1000 * 60 * 60 * 24);
        return daysSinceLastSeen >= 30;
      }
      
      return daysSinceRegistration >= 14;
    });
  }, [patients]);

  // Handle Log Out
