  const handleAttachmentUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!timelinePatient || !e.target.files || e.target.files.length === 0) return;
    const file = e.target.files[0];
    
    const folderId = timelinePatient.folderId || timelinePatient.id;
    if (!folderId) {
      alert("This patient record does not have a Google Drive folder set up. Cannot upload attachment.");
      return;
    }

    setUploadingAttachment(true);
    try {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = async () => {
        const base64Str = (reader.result as string).split(",")[1];
        
        const response = await fetch("/api/patient/attachment", {
          method: "POST",
          headers: {
            "Content-Type": "application/json"
          },
          body: JSON.stringify({
            patientId: timelinePatient.id,
            folderId: folderId,
            fileName: file.name,
            fileMimeType: file.type || "application/octet-stream",
            fileData: base64Str
          })
        });

        const result = await response.json();
        if (result.success) {
          alert(`Successfully uploaded "${file.name}" to Google Drive and synced to clinical ledger!`);
          
          const updatedPatient = {
            ...timelinePatient,
            attachments: [...(timelinePatient.attachments || []), result.attachment]
          };
          setTimelinePatient(updatedPatient);
          setPatients(prev => prev.map(p => p.id === timelinePatient.id ? updatedPatient : p));
        } else {
          alert(`Upload failed: ${result.message}`);
        }
      };
    } catch (err: any) {
      console.error(err);
      alert(`Error uploading file: ${err.message || err}`);
    } finally {
      setUploadingAttachment(false);
    }
  };

  const handleAddTimelinePrescription = async () => {
    if (!timelinePatient || !timelinePrescriptionText.trim()) return;

    try {
      const dbRef = doc(db, "patients", timelinePatient.id);
      const newPrescription = {
        remedy: timelinePrescriptionText,
        potency: timelinePrescriptionPotency,
        prescribedAt: new Date().toISOString()
      };

      const currentPrescriptions = (timelinePatient as any).prescriptions || [];
      const updatedPrescriptions = [...currentPrescriptions, newPrescription];

      await updateDoc(dbRef, {
        prescriptions: updatedPrescriptions,
        lastSeen: new Date().toISOString()
      });

      const updatedPatient = {
        ...timelinePatient,
        prescriptions: updatedPrescriptions,
        lastSeen: new Date().toISOString()
      };
      setTimelinePatient(updatedPatient);
      setPatients(prev => prev.map(p => p.id === timelinePatient.id ? updatedPatient : p));
      setTimelinePrescriptionText("");
      alert("Prescription added to clinical record and synced!");
    } catch (err: any) {
      console.error("Failed to add prescription:", err);
      alert(`Error saving prescription: ${err.message || err}`);
    }
  };

  // Helper to handle mouse hover subtabs navigation
  const handleSubTabClick = (
    tabId: "dashboard" | "intake" | "patients" | "diagnostics" | "analyzer" | "diet-lifestyle" | "treatment-planner" | "nexus-atlas" | "learning-hub" | "communication" | "ai-router" | "health-intelligence" | "cie" | "medical-academy",
    subSectionId: string,
    action?: () => void
  ) => {
    setActiveTab(tabId as any);
    if (tabId === "cie") {
      if (subSectionId === "cie-cockpit") setCieSubTab("cockpit");
      else if (subSectionId === "cie-intake") setCieSubTab("intake");
      else if (subSectionId === "cie-miasms") setCieSubTab("miasms");
      else if (subSectionId === "cie-reports") setCieSubTab("reports");
    }
    if (tabId === "medical-academy") {
      const modeMap: Record<string, string> = {
        "academy-home": "dashboard",
        "academy-learn": "learn",
        "academy-explore": "explore",
        "academy-practice": "practice",
        "academy-assess": "assess",
        "academy-research": "research",
        "academy-certify": "certify"
      };
      const mode = modeMap[subSectionId];
      if (mode) {
        setAcademyMode(mode);
        if (academyIframeRef.current?.contentWindow) {
          academyIframeRef.current.contentWindow.postMessage({
            type: "cios-academy-mode-switch",
            mode: mode
          }, "*");
        }
      }
    }
    if (action) {
      action();
    }
    setTimeout(() => {
      const element = document.getElementById(subSectionId);
      if (element) {
        element.scrollIntoView({ behavior: "smooth", block: "start" });
      }
    }, 150);
  };




  const getOptionLabel = (baseLabel: string, monthlyPrice: number) => {
    const isWeekly = newCaseForm.billingCycle === "Weekly";
    const basePrice = getCareLevelRate(baseLabel, newCaseForm.billingCycle, newCaseForm.conditionsCount);
    
    if (newCaseForm.durationText.includes("One-Time")) {
      return `${baseLabel} (₹${basePrice.toLocaleString("en-IN")} One-time)`;
    }
    const val = getDurationValue(newCaseForm.durationText);
    if (val === 1) {
      return `${baseLabel} (₹${basePrice.toLocaleString("en-IN")}/${isWeekly ? "wk" : "mo"})`;
    }
    return `${baseLabel} (₹${(basePrice * val).toLocaleString("en-IN")} for ${val} ${isWeekly ? "weeks" : "months"})`;
  };

  const calculateCaseFormPricing = (
    level: string,
    durationText: string,
    age: string,
    discountOverride: number,
    billingCycle: string,
    concessionType: string,
    conditionsCount: number = 1,
    manualFinalPrice?: number
  ) => {
    const rate = getCareLevelRate(level, billingCycle, conditionsCount);
    const val = getDurationValue(durationText);
    const base = rate * val;
    
    const discountPercent = 0;
    const durationDiscountAmount = 0;
    const concessionDiscountAmount = 0;
    const afterDurationDiscount = base;
    let calculatedFinal = base;
    
    if (concessionType === "Override") {
      calculatedFinal = Math.max(0, afterDurationDiscount - discountOverride);
    }
    
    const finalPrice = manualFinalPrice !== undefined ? manualFinalPrice : calculatedFinal;
    
    return {
      basePrice: base,
      discountPercent,
      durationDiscountAmount,
      seniorDiscountAmount: 0,
      socioDiscountAmount: 0,
      calculatedFinal,
      finalPrice
    };
  };

  const handleCareLevelChange = (level: string) => {
    const pricing = calculateCaseFormPricing(level, newCaseForm.durationText, newCaseForm.age, newCaseForm.discountOverride, newCaseForm.billingCycle, newCaseForm.concessionType, newCaseForm.conditionsCount);
    setNewCaseForm(prev => ({
      ...prev,
      careLevel: level,
      basePrice: pricing.basePrice,
      finalPrice: pricing.finalPrice,
      receivedAmount: pricing.finalPrice,
      remainingBalance: 0
    }));
  };

  const handleGenerateRecommendation = () => {
    const levelVal = newCaseForm.careLevel;
    const key = normalizeCareLevelName(levelVal);

    const durVal = newCaseForm.durationText;
    const match = durVal.match(/^(\d+)/);
    const duration = match ? parseInt(match[1]) : 1;
    const cycle = newCaseForm.billingCycle.toLowerCase() as "weekly" | "monthly";

    const rec = getTreatmentRecommendation(
      key,
      newCaseForm.conditionsCount,
      duration,
      cycle
    );

    setNewCaseRecommendationText({
      complexity: rec.complexity,
      followUpFrequency: rec.followUpFrequency,
      patientExplanation: rec.patientExplanation
    });
  };

