      setConstMiasmIndicators(["Psora"]);
      setConstMentalState("");
      setConstEmotionalPattern("Anxious/Restless");
      setDiagDiagnosis("");
      setDiagLabs("");
      setDiagImaging("");
      setDiagPastTreatments("");
      setDiagCurrentMeds("");
      setSynthesisOutput(null);
      setIntakeResult(null);
